update item_def set description = 'No effect until restored. Restoration difficulty by grade: minor 15, major 30, ancient 45; effect and rarity set at random then. Cannot be repaired before then; gone if it breaks.' where id = 'tarnished_bauble';
update item_def set description = 'Set in one of the 21 minor sockets of your settlement''s altar. Citizens working there get its effect on that one skill: less time per action, or more skill gained.' where id = 'bauble_minor';
update item_def set description = 'Set in one of the 5 major sockets of your settlement''s altar. Citizens working there get its chance of 2× the yield per action in that one skill.' where id = 'bauble_major';
update item_def set description = 'Undoes a class, patron or path, this used up. Undo on your class (Trades window): removed with its perks or tree. Take on another class in a held slot: uses one. Undo on your patron or path (Faith window): removed with its spells or picks, off the spell bar.' where id = 'bauble_regret';
update item_def set description = 'Left by 1% of altar sacrifices, at the rarity of what was given. Absorb into (on the soul): an ordinary thing in your pack, or one of a stack, takes its rarity. Used up.' where id = 'soul';
update item_def set description = 'Set in one of the 3 ancient sockets of your settlement''s altar. Citizens working there get its bonus added to every yield of that one action.' where id = 'bauble_ancient';
update item_def set description = 'Use on your wildermon (its menu): its next covering''s young get its best trait (highest rarity; first listed on a tie) at that rarity, in place of a draw. One mark at a time, used up at that covering. Used up.' where id = 'bronze_mirror';
update item_def set description = 'Use on your wildermon (its menu): one age younger. Old → grown (as if just grown); grown → young (as if just born). Old: 85% speed, 80% pull. Grown: full. Young: cannot work, be ridden or pull. No effect on young. Used up.' where id = 'ancient_comb';
update item_def set description = 'Use on your wildermon (its menu): 1 in 20, one rarity step up: ordinary → rare → supreme → fantastic. Every blood figure at rare, supreme, fantastic: +20%, +40% and +60% of an ordinary one; drawn bigger. Used up either way.' where id = 'ancient_file';
update item_def set description = 'Use on your wildermon (its menu): rerolls its lowest-rarity trait (random among ties) to one it lacks, same rarity, or 1 in 20 one rarity up (common to rare, rare to supreme and supreme to fantastic). Never lower. At fantastic: always another fantastic trait. Under 3 traits: fills the empty slot, common, or 1 in 20 rare. Used up.' where id = 'ancient_lamp';
update item_def set description = 'Use on your wildermon (its menu): one point to a random base stat under 10: health (max health), attack (blow damage), speed (pace on foot, under a rider and in the traces) and work (task speed). Each point: 3% more of that stat over its kind and blood. Max 10 per stat. Used up.' where id = 'ancient_pot';
update item_def set description = 'Use on your wildermon (its menu): upkeep (hunger rate) −20%, for good. Once per wildermon. Used up.' where id = 'ancient_collar';
update item_def set description = 'Use on your wildermon (its menu): speed ridden and in a team +10%, past the speed cap, for good. Once per wildermon. Used up.' where id = 'ancient_bridle';
update item_def set description = 'Use on your wildermon (its menu): action (task) speed +1% a use, up to 50 uses (+50%). Used up.' where id = 'ancient_brace';
update item_def set description = 'Hone with it (on a damaged tool or weapon in your pack): all damage off, QL kept. Used up.' where id = 'ancient_whetstone';
update item_def set description = 'Open: 5 seeds of one of 13 crops at random, at the jar''s QL. Used up.' where id = 'ancient_seed_jar';
update item_def set description = 'Carried: rare chance ×2 on your next 5 crafts and forgings. One go each; used up after the last.' where id = 'ancient_stamp';
update item_def set description = 'Read (Skills window, Rune tablet on a skill under 50): that skill +1.0. Used up.' where id = 'rune_tablet';
update item_def set description = 'Worn: sight radius +3 tiles. Cannot be improved or repaired.' where id = 'ancient_helm';
