update item_def set description = 'Fit on your small wildermon (its menu; first evolution stage, or non-evolving under 25 health): team pace in the traces of a cart or wagon +5% at QL 0 to +10% at QL 100, its share of the team. Wears a tile pulled. Damage 100: falls apart. Remove to repair.' where id = 'wild_harness_small';
